import{c as t,Q as e,j as o,m as p}from"./chunks/framework.hhGiamYR.js";const q=JSON.parse('{"title":"你的首要技艺是什么——马基雅维利关于专注的最极端主张","description":"","frontmatter":{"date":"2026-08-09T00:00:00.000Z","title":"你的首要技艺是什么——马基雅维利关于专注的最极端主张"},"headers":[],"relativePath":"research/princes-primary-art/index.md","filePath":"research/princes-primary-art/index.md"}'),a={name:"research/princes-primary-art/index.md"};function n(l,r,i,u,c,s){return e(),o("div",null,[...r[0]||(r[0]=[p('<p>1494 年，法王查理八世率大军翻越阿尔卑斯山，穿过意大利如入无人之境——那不勒斯王国在他面前瓦解，佛罗伦萨在他面前屈服。整个过程不到五个月。我当时还不在政府任职，但我亲眼看到了那些曾经显赫一时的意大利君主们面对这场入侵时的姿态：不是抵抗，而是跑——或者更糟：谈判。他们之中没有一个人能打。</p><p>这件事在我心里生了根。二十年后，当我坐在圣卡夏诺乡下那间书房里写《君主论》时，我把那个五月的耻辱凝成了最简单的一句话——一句话，我敢说，比我在那本书里写的任何东西都更让后来的人们不舒服：</p><blockquote><p>📖 <strong>原文</strong>：《君主论》第14章</p><p>&quot;一位君主除了战争及其规章制度和训练之外，不应该有其他的目标、其他任何的思想，也不应该把其他任何事情作为他的技艺，因为这是发号施令者应当关注的唯一技艺。它的效力不仅能够使那些凭出身成为君主的人维持地位，而且多次使那些平民运道的人跃居君主之位；反之，我们则看到，君主一旦考虑安逸享乐甚于整军经武，就会失去他们的国家。导致你失去国家的头一个原因就是忽略了这种技艺，而使你获取国家的原因就是你精通这种技艺。&quot;</p><p>— 全文阅读：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/prince/prince-cn-full.md" target="_blank" rel="noreferrer">《君主论》第14章</a></p></blockquote><p>这句话让我的批评者们跳脚了五百年。&quot;除了战争什么也不要想&quot;——听上去像是一个军国主义疯子的宣言。儒雅的学者们翻开第14章，立刻合上书，宣布我是一个危险人物。他们完全误解了我。</p><p>我不是在说每个人都应该拿起长矛。我是在说一个更根本的东西：<strong>每一个肩负责任的人，都必须知道他的&quot;战争&quot;是什么——他的首要技艺是什么——并且永远不要因为安逸而荒废它。</strong></p><hr><h2 id="斯福尔扎父子-一个教科书般的对照实验" tabindex="-1">斯福尔扎父子：一个教科书般的对照实验 <a class="header-anchor" href="#斯福尔扎父子-一个教科书般的对照实验" aria-label="Permalink to &quot;斯福尔扎父子：一个教科书般的对照实验&quot;">​</a></h2><p>我在《君主论》里给出了一个完美的例子，刚好跨越两代人。</p><p>弗朗切斯科·斯福尔扎（Francesco Sforza, 1401–1466）是一个雇佣兵队长的私生子。他没有王室血统，没有世袭领地，没有教皇做靠山。他有的只是一项技艺：战争。他用一生磨练它。他带领自己的军队，与威尼斯人打，与米兰人打，与佛罗伦萨人打。1450 年，他率军进入米兰，由一介平民跃升为公爵。&quot;他获取其地位历尽千辛万苦，而维持其地位却轻松异常&quot;——我在第 7 章这样写道。</p><p>然后他的儿子们继承了米兰。路德维科·斯福尔扎（绰号&quot;摩尔人&quot;）喜欢艺术、文学、达·芬奇——唯独不喜欢亲自带兵。他和他的兄弟们&quot;躲避军事的艰苦&quot;。</p><p>结果呢？</p><blockquote><p>📖 <strong>原文</strong>：《君主论》第14章</p><p>&quot;弗朗切斯科·斯福尔扎武装了自己，于是由一介平民跃升为米兰的公爵；而他的儿子们躲避军事的艰苦，结果由公爵降为平民。&quot;</p><p>— 全文阅读：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/prince/prince-cn-full.md" target="_blank" rel="noreferrer">《君主论》第14章</a></p></blockquote><p>一个家庭，两代人。父亲精通战争技艺，从零到公爵；儿子们荒废了它，从公爵到阶下囚。这不是命运捉弄——这是忽略了首要技艺的自然结果。路德维科于 1499 年被法军驱逐，1500 年被俘，1508 年死在法国的一间地牢里。</p><p>这不是偶然。我在《君主论》第 24 章又审视了一遍我们这个时代丢掉国家的意大利君主们——那不勒斯国王、米兰公爵，还有一些其他人。他们的共同点不是运气不好。他们的共同点是：<strong>军队有缺陷</strong>，然后才是其他问题——失民心、权贵失控。但是&quot;如果没有这些缺陷，只要有足够的力量让一支军队决战于疆场，他们就不会失去国家。&quot;</p><p>请注意我这句话的次序。我先说军队，再说民心。不是因为民心不重要——而是因为民心问题的暴露需要一个条件：就是当敌人打到你门口的时候，你没有一支军队来保护自己。<strong>首要技艺即是保护你所有其他技艺不被摧毁的那个技艺。</strong></p><hr><h2 id="菲洛皮门-一个在和平时期没有哪一天不想着战争的疯子" tabindex="-1">菲洛皮门：一个在和平时期没有哪一天不想着战争的疯子 <a class="header-anchor" href="#菲洛皮门-一个在和平时期没有哪一天不想着战争的疯子" aria-label="Permalink to &quot;菲洛皮门：一个在和平时期没有哪一天不想着战争的疯子&quot;">​</a></h2><p>如果斯福尔扎父子是反面教材，那么下面这个人是正面标杆。</p><p>菲洛皮门（Philopoemen，公元前 253–前 183 年），亚该亚同盟的统帅。古代作家们对他赞不绝口，但让他们印象最深的不是他打了多少胜仗——而是这样一个细节：</p><blockquote><p>📖 <strong>原文</strong>：《君主论》第14章</p><p>&quot;即使在和平时期，他也没有思考过战争方式之外的任何事情；当他和朋友们在乡村野外的时候，他常常停下来同他们探讨：如果敌人在那个山丘上，而我们和我们的军队在这里，谁占有优势呢？如何才能迎面应战而维持秩序呢？如果我们想从这里撤退，我们应该怎么做呢？如果敌人撤退了，我们应该怎么追击呢？当他和他们一起散步的时候，他会向他们提出一支军队可能遇到的各种风险，他倾听他们的意见，并说出自己的意见，提出各种理由加以论证。由于这些持续的深谋远虑，他在率领军队时就绝不可能发生任何他没有补救办法的意外事件。&quot;</p><p>— 全文阅读：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/prince/prince-cn-full.md" target="_blank" rel="noreferrer">《君主论》第14章</a></p></blockquote><p>一个在和平时期比在战争时期更专注的人。朋友们在散步、聊天、欣赏风景，他在脑子里推演战术。请注意我在这里强调的：<strong>和平时期比战争时期更加需要训练。</strong> 暴风雨让每一个船长都紧张起来；但在风平浪静时还在练习掌舵的船长，才是真正不会沉船的那一个。</p><p>我的意思是写在书里的，一个字都不用改：</p><blockquote><p>&quot;一位明智的君主应当遵循这些方式，在和平时期绝不能无所事事，相反，应该费尽心机利用它们，以便在身处逆境时能够从中受益；这样，在机运逆转的时候，人们会发现他已经做好了抗击它们的准备。&quot;</p></blockquote><hr><h2 id="这不止是说给君主听的" tabindex="-1">这不止是说给君主听的 <a class="header-anchor" href="#这不止是说给君主听的" aria-label="Permalink to &quot;这不止是说给君主听的&quot;">​</a></h2><p>如果你不是君主，你可能会想：这跟我有什么关系？</p><p>让我换一种说法。你不必统治米兰，但你在你的位置上同样有一个&quot;战争&quot;——一个你如果忽略了它，你的一切都会崩塌的东西。</p><p>对医生来说，是诊断的能力。失去它，你对病人就毫无价值。 对商人来说，是判断市场供需的能力。失去它，你的财富会自己消散。 对老师来说，是让学生理解的能力。失去它，你站在讲台上和一块石头没区别。 对我的国务秘书生涯来说，是分析和书写。我写了几百封外交急件——每一封都要求我在有限的信息中推断对方的真实意图，然后用最精确的语言呈报给十人委员会。我可以喝酒、开玩笑、在酒馆里讲不堪入耳的故事——但当坐到书桌前的那一刻，我必须拿出我的首要技艺。这是我的斯福尔扎时刻：不是靠血统，不是靠关系，而是靠手艺。</p><p>第 14 章表面上在谈战争，但它的逻辑适用于任何一个需要承担责任的人。你的&quot;军队&quot;——你依赖它保护你的事物、你通过它获取地位的事物——究竟是什么？你有没有像菲洛皮门那样，在风和日丽的时候，还在一遍一遍地问自己：&quot;如果敌人出现在那个山丘上，我该怎么办？&quot;</p><p>如果你正在回避这个问题——如果你现在一切顺利，于是不再磨练让你顺利的那项技艺——我要坦白地对你说：你在重复路德维科·斯福尔扎的错误。而路德维科死在法国的一间牢房里，死的时候什么都不是。</p><p>我不希望任何人重复他。所以我写了第 14 章。</p><hr><p>尼科洛·马基雅维利，圣卡夏诺</p>',33)])])}const m=t(a,[["render",n]]);export{q as __pageData,m as default};
